-- Profilkes Batch 1 — Profilkes Indicators (Resume, Tabel 1, 6, 7, 8)
-- Source: Tabel_Profilkes_2025_Final.xlsx (Kabupaten Situbondo, 2025)
-- Values are the Excel cached values (data_only), NOT formulas.
-- Excel errors (#DIV/0!, #REF!) are seeded as NULL with data_quality_flag='source_error'.
-- Percentages > 100% and zero doctor ratios are seeded as-is with
-- data_quality_flag='..._needs_confirmation' (user decision 2026-11-25: show as-is + flag).
-- Idempotent: ON DUPLICATE KEY UPDATE, unique key (report_year, source_table, metric_code, region_name).
-- 2026-11-25: section widened VARCHAR(10) -> VARCHAR(50). Batch 1 only stored
-- Roman numerals (I-VII); Batch 2 stores 'RUMAH SAKIT'/'SARANA LAINNYA' (11/14 chars)
-- and seeding failed with ERROR 1406 at row 169 before this fix.

CREATE TABLE IF NOT EXISTS profilkes_indicators (
    id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    report_year SMALLINT UNSIGNED NOT NULL,
    source_table VARCHAR(20) NOT NULL,
    metric_code VARCHAR(100) NOT NULL,
    metric_name VARCHAR(255) NOT NULL,
    section VARCHAR(50) NULL,
    section_name VARCHAR(100) NULL,
    region_type VARCHAR(50) NOT NULL,
    region_name VARCHAR(100) NOT NULL,
    male DECIMAL(20, 8) NULL,
    female DECIMAL(20, 8) NULL,
    total DECIMAL(20, 8) NULL,
    percentage DECIMAL(20, 8) NULL,
    unit VARCHAR(50) NULL,
    source_reference VARCHAR(255) NULL,
    extra_code VARCHAR(255) NULL,
    data_quality_flag VARCHAR(100) NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY uq_profilkes_indicator (report_year, source_table, metric_code, region_name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

